/// <summary>
/// PaffH 30.01.24
/// generate batchjob and task for: get RicoKalk quotations 6 month
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXRicoBVAdministration, FormButtonCreateNewBatchJobGetQuotations3Month), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void FormButtonCreateNewBatchJobGetQuotations3Month_OnClicked(FormControl sender, FormControlEventArgs e)
{
    KCS_KBVParameters kCS_KBVParameters = KCS_KBVParameters::find(true);
    if (kCS_KBVParameters.NDXBatchHeaderRefRecIdRicoKalkGetQuotations3Month &&
        Box::yesNo("@NDX:NDXBatchJobAssignementExistsIgnore", DialogButton::No) == DialogButton::No)
    {
        return;
    }

    NDXBatchJobRicoBVArgs args = NDXBatchJobRicoBVArgs::construct();
    date today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    const int DaysInFuture = 1;
    date startDate = today + DaysInFuture;
    utcdatetime startAt = DateTimeUtil::newDateTime(startDate, str2Time('07:30:00'), DateTimeUtil::getUserPreferredTimeZone());
    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, startAt);
    sysRecurrenceData = SysRecurrence::setRecurrenceNoEnd(sysRecurrenceData);
    sysRecurrenceData = SysRecurrence::setRecurrenceUnit(sysRecurrenceData, SysRecurrenceUnit::Hour, 1);
    args.parmRecurrenceData(sysRecurrenceData);
    args.parmCaption("@NDXRicoBV:NDXBatchJobRicoKalkQuotations3Month2");
    args.parmController(NDXRicoKalkGetQuotationController3Month::construct());
    args.parmBatchJobActivePeriodId(NDXRicoKalkGetQuotationController::getPeriodId_07_21());
    NDXRicoKalk2KBVBuildingProjectContract contract = args.parmContract();
    contract.initialize();
    contract.parmCheckDays(90);

    NDXBatchJobRicoKalkQuotationGet nDXBatchJobRicoKalkQuotationGet = NDXBatchJobRicoKalkQuotationGet::construct();
    RefRecId refRecId = nDXBatchJobRicoKalkQuotationGet.addTask(args);
    ttsbegin;
    kCS_KBVParameters.NDXBatchHeaderRefRecIdRicoKalkGetQuotations3Month = refRecId;
    kCS_KBVParameters.update();
    ttscommit;

    FormRun formRun = sender.formRun();
    FormRunDataHelper dataHelper = formRun.dataHelper();
    dataHelper.FindDataSource(formDataSourceStr(NDXRicoBVAdministration, BatchJob_GetQuotations3Month)).research(true);
    dataHelper.FindDataSource(formDataSourceStr(NDXRicoBVAdministration, Batch_GetQuotations3Month)).research(true);
}

