/// <summary>
/// PaffH 04.04.24
/// generate batchjob and task for: log clean up
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(NDXRicoBVAdministration, FormButtonCreateNewBatchJobGetQuotationsLogCleanUp), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void FormButtonCreateNewBatchJobGetQuotationsLogCleanUp_OnClicked(FormControl sender, FormControlEventArgs e)
{
    KCS_KBVParameters kCS_KBVParameters = KCS_KBVParameters::find(true);
    if (kCS_KBVParameters.NDXBatchHeaderRefRecIdRicoKalkLogCleanup &&
        Box::yesNo("@NDX:NDXBatchJobAssignementExistsIgnore", DialogButton::No) == DialogButton::No)
    {
        return;
    }

    NDXBatchJobRicoBVArgs args = NDXBatchJobRicoBVArgs::construct();
    date today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    const int DaysInFuture = 1;
    date startDate = today + DaysInFuture;
    utcdatetime startAt = DateTimeUtil::newDateTime(startDate, str2Time('19:30:00'), DateTimeUtil::getUserPreferredTimeZone());
    SysRecurrenceData sysRecurrenceData = SysRecurrence::defaultRecurrence();
    sysRecurrenceData = SysRecurrence::setRecurrenceStartDateTime(sysRecurrenceData, startAt);
    sysRecurrenceData = SysRecurrence::setRecurrenceNoEnd(sysRecurrenceData);
    sysRecurrenceData = SysRecurrence::setRecurrenceUnit(sysRecurrenceData, SysRecurrenceUnit::Day, 1);
    args.parmRecurrenceData(sysRecurrenceData);
    args.parmCaption("@NDXRicoBV:NDXBatchJobRicoKalkQuotationsLogCleanUp2");
    args.parmController(NDXRicoKalkGetQuotationControllerLogCleanUp::construct());
    args.parmBatchJobActivePeriodId(NDXRicoKalkGetQuotationController::getPeriodId_18_24());
    NDXRicoKalk2KBVBuildingProjectContract contract = args.parmContract();
    contract.initialize();
    contract.parmFromDateOffset(30);
    contract.parmProtKopftyp(NDXProtKopfTyp::RicoKalk_Angebot_Abgleich);

    NDXBatchJobRicoKalkQuotationGet nDXBatchJobRicoKalkQuotationGet = NDXBatchJobRicoKalkQuotationGet::construct();
    RefRecId refRecId = nDXBatchJobRicoKalkQuotationGet.addTask(args);
    ttsbegin;
    kCS_KBVParameters.NDXBatchHeaderRefRecIdRicoKalkLogCleanup = refRecId;
    kCS_KBVParameters.update();
    ttscommit;

    FormRun formRun = sender.formRun();
    FormRunDataHelper dataHelper = formRun.dataHelper();
    dataHelper.FindDataSource(formDataSourceStr(NDXRicoBVAdministration, BatchJob_GetQuotationsLogCleanUp)).research(true);
    FormDataSource fds = dataHelper.FindDataSource(formDataSourceStr(NDXRicoBVAdministration, Batch_GetQuotationsLogCleanUp));
    //QueryBuildDataSource qbds = fds.query().dataSourceNo(1);
    //SysQuery::findOrCreateRange(qbds, fieldNum(Batch, BatchJobId)).value(SysQuery::valueNot(refRecId));
    fds.research(true);
}

