/// <summary>
/// PaffH 26.05.25
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(NDXRicoBVAdministration, FormButtonNDX_KBV2RicoProtLineCleanup), FormControlEventType::Clicked)]
public static void FormButtonNDX_KBV2RicoProtLineCleanup_OnClicked(FormControl sender, FormControlEventArgs e)
{
    NDX_KBV2RicoProtLine nDX_KBV2RicoProtLine;
    update_recordset nDX_KBV2RicoProtLine
        setting KBVProtIDInt = -1
        where nDX_KBV2RicoProtLine.KBVProtIDInt == 0;
    Info(strFmt("@NDXBase:NDXCorrectedRecordsInTable", nDX_KBV2RicoProtLine.RowCount(), tableId2Name(tableNum(NDX_KBV2RicoProtLine))));
}
